model_blob = dict(idef['model'])
# Rule: if modelName is null, use modelDisplayName
if not model_blob.get('modelName'):
    model_blob['modelName'] = model_blob['modelDisplayName']

outdef_output = ixp_reg['outputDefinition']['output']
outdef_error = ixp_reg['outputDefinition']['error']

