        "isDefaultEntryPoint": True
      }
    },
    {
      "id": "extractReceiptFields",
      "type": "uipath.ixp.idp-benchmark-receipts-43af6412-ixp.9e77f71d-773c-80a0-9411-ec40d252d00d-c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
      "typeVersion": "1.0.0",
      "display": {"label": "Extract Receipt Fields"},
      "inputs": {
        "model": model_blob,
        "modelName": idef.get('modelName') or model_blob['modelDisplayName'],
        "projectName": idef.get('projectName') or model_blob['modelDisplayName'],
        "folderKey": idef.get('folderKey'),
        "folderName": idef.get('folderName'),
        "versionTag": "",
        "pageRange": "",
